function make(){
  const r=NV.rng(77031);const today=TODAY;
  const companies=COMPANIES.map(([name,city,prov,ind,emp],i)=>({id:"C"+String(i+1).padStart(3,"0"),name,city,prov,industry:INDUSTRIES[ind],employees:emp,web:"www."+slug(name)+".com.ar",phone:"+54 "+r.int(221,385)+" "+r.int(400,799)+"-"+r.int(1000,9999),owner:REPS[i%4].id,status:i<16?"customer":"prospect",rating:r.int(2,5),created:iso(addDays(today,-r.int(60,1500))),cuit:"30-"+r.int(50000000,71999999)+"-"+r.int(0,9),notes:""}));
  const contacts=[];companies.forEach(c=>{for(let k=0;k<r.int(1,3);k++){const fn=r.pick(FIRST),ln=r.pick(LAST);contacts.push({id:"P"+String(contacts.length+1).padStart(3,"0"),name:fn+" "+ln,company:c.id,role:r.pick(ROLES),email:(fn[0]+ln).toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g,"")+"@"+slug(c.name)+".com.ar",phone:"+54 9 "+r.int(221,385)+" "+r.int(400,799)+"-"+r.int(1000,9999),last:iso(addDays(today,-r.int(0,60))),tags:r.chance(.3)?["decisor"]:[]})}});
  const opps=[];
  for(let i=0;i<34;i++){const c=r.pick(companies);const ct=contacts.filter(x=>x.company===c.id);const created=addDays(today,-r.int(5,200));const age=(today-created)/864e5;
    let st=age>120?r.pick(["won","won","lost","lost","won"]):age>60?r.pick(["won","lost","negotiation","proposal","won"]):age>25?r.pick(["proposal","negotiation","qualify","proposal","won","lost"]):r.pick(["prospect","qualify","qualify","proposal"]);
    const amount=r.pick([8,12,18,24,35,48,62,85,120,160])*1000+r.int(0,9)*100;
    const close=st==="won"||st==="lost"?addDays(created,r.int(20,Math.max(21,Math.min(140,age-1)))):addDays(today,r.int(3,95));
    const S=STAGES.find(s=>s.id===st);const hist=[{d:iso(created),txt:tr("Oportunidad creada","Opportunity created")}];
    const order=STAGES.map(s=>s.id);const idx=order.indexOf(st);for(let k=1;k<=Math.min(idx,3);k++)hist.push({d:iso(addDays(created,k*Math.max(2,Math.round(age/6)))),txt:tr("Etapa → ","Stage → ")+NV.L(STAGES[k].name)});if(st==="won"||st==="lost")hist.push({d:iso(close),txt:tr("Etapa → ","Stage → ")+NV.L(S.name)});
    opps.push({id:"O"+String(i+1).padStart(3,"0"),ref:"OP-"+String(240+i),title:NV.L(r.pick(OPP_TITLES)),company:c.id,contact:ct.length?r.pick(ct).id:"",amount,stage:st,prob:S.p,close:iso(close),owner:c.owner,source:r.pick(SOURCES)[0],created:iso(created),lost:st==="lost"?r.pick(LOST):null,next:st==="won"||st==="lost"?"":r.pick([["Enviar propuesta técnica","Send technical proposal"],["Visita a planta","Plant visit"],["Llamar para seguimiento","Follow-up call"],["Revisar planos con ingeniería","Review drawings with engineering"],["Negociar condiciones de pago","Negotiate payment terms"]]),hist});}
  opps.forEach(o=>{if(o.stage==="won")companies.find(c=>c.id===o.company).status="customer"});
  const leads=[];const LCOMP=["Lácteos Trenque Lauquen","Aserradero Misiones","Metalúrgica Tandil","Olivícola Catamarca","Textil Chaco","Frigorífico Entre Ríos","Fundición San Francisco","Hidráulica Junín","Arenera Paraná","Maltería Tres Arroyos","Vidriera Mendoza","Biodiesel Santa Fe","Curtiembre Esperanza","Yerbatera Oberá","Pesquera Madryn","Galvanizadora Rosario","Avícola Concepción","Papelera Zárate","Cerámica Olavarría","Aceros Villa Constitución","Mosto Sanjuanino","Hormigonera Neuquén"];
  LCOMP.forEach((cn,i)=>{const fn=r.pick(FIRST),ln=r.pick(LAST);const created=addDays(today,-r.int(0,45));const age=(today-created)/864e5;leads.push({id:"L"+String(i+1).padStart(3,"0"),name:fn+" "+ln,company:cn+" "+r.pick(["S.A.","S.R.L."]),role:r.pick(ROLES),email:(fn+"."+ln).toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g,"")+"@"+slug(cn)+".com.ar",phone:"+54 9 "+r.int(221,385)+" "+r.int(400,799)+"-"+r.int(1000,9999),source:r.pick(SOURCES)[0],status:age>25?r.pick(["qualified","lost","contacted"]):age>7?r.pick(["contacted","qualified","new"]):r.pick(["new","new","contacted"]),score:r.int(15,95),owner:REPS[r.int(0,3)].id,created:iso(created),interest:NV.L(r.pick(CATALOG)[1]),industry:r.pick(INDUSTRIES),city:r.pick(["Córdoba","Rosario","Mendoza","Tucumán","Neuquén","Mar del Plata","Salta","Bahía Blanca"])})});
  const acts=[];const TYPES=["call","meeting","email","visit","task"];
  const ATXT={call:[["Llamada de seguimiento","Follow-up call"],["Llamada para relevar necesidad","Discovery call"]],meeting:[["Reunión técnica por videollamada","Technical video meeting"],["Presentación de propuesta","Proposal presentation"]],email:[["Enviar ficha técnica y plazos","Send datasheet and lead times"],["Email con cotización revisada","Email revised quote"]],visit:[["Visita a planta del cliente","Customer plant visit"],["Relevamiento en obra","On-site survey"]],task:[["Preparar cotización","Prepare quote"],["Pedir planos a ingeniería","Request drawings from engineering"],["Actualizar CRM tras feria","Update CRM after trade show"]]};
  for(let i=0;i<84;i++){const o=r.chance(.8)?r.pick(opps):null;const c=o?o.company:r.pick(companies).id;const day=addDays(today,r.int(-32,34));const h=r.pick([8,9,9,10,11,11,12,14,15,15,16,17]);const dt=new Date(day);dt.setHours(h,r.pick([0,0,30,15,45]),0,0);const type=r.pick(TYPES);
    acts.push({id:"A"+String(i+1).padStart(3,"0"),type,title:NV.L(r.pick(ATXT[type])),dt:dt.toISOString(),dur:type==="visit"?120:type==="meeting"?60:type==="task"?0:20,company:c,opp:o?o.id:"",owner:o?o.owner:REPS[r.int(0,3)].id,done:dt<today?r.chance(.88):false,notes:""})}
  // a few today
  [9,11,15,17].forEach((h,k)=>{const dt=new Date(today);dt.setHours(h,k%2?30:0,0,0);const o=opps[k*3];acts.push({id:"A9"+k,type:TYPES[k],title:NV.L(ATXT[TYPES[k]][0]),dt:dt.toISOString(),dur:30,company:o.company,opp:o.id,owner:"U1",done:false,notes:""})});
  acts.sort((a,b)=>a.dt.localeCompare(b.dt));
  const quotes=[];opps.filter(o=>["proposal","negotiation","won","lost"].includes(o.stage)).slice(0,16).forEach((o,i)=>{const d=addDays(D2(o.created),r.int(3,15));let left=o.amount/1.21;const lines=[];const items=r.int(1,3);for(let k=0;k<items;k++){const it=CATALOG[r.int(0,7)];const q=Math.max(1,Math.round(left/(items-k)/it[2]));lines.push({p:it[0],desc:it[1],q,price:it[2],disc:r.pick([0,0,5,8])});left-=q*it[2]}if(r.chance(.5))lines.push({p:"SV-960",desc:CATALOG[9][1],q:r.int(1,4),price:420,disc:0});
    quotes.push({id:"Q"+String(i+1).padStart(3,"0"),ref:"CT-26-"+String(310+i),opp:o.id,company:o.company,contact:o.contact,date:iso(d),valid:iso(addDays(d,30)),lines,status:o.stage==="won"?"accepted":o.stage==="lost"?"rejected":r.pick(["sent","sent","draft"]),terms:r.pick(["30 días fecha factura","50% anticipo, 50% contra entrega","60 días"]),delivery:r.pick(["15 días hábiles","20 días hábiles","30 días hábiles"]),notes:""})});
  const tickets=[];for(let i=0;i<20;i++){const c=r.pick(companies.filter(x=>x.status==="customer"));const ct=contacts.filter(x=>x.company===c.id);const created=new Date(addDays(today,-r.int(0,40)));created.setHours(r.int(8,17),r.int(0,59));const age=(today-created)/864e5;const s=r.int(0,TSUBJ.length-1);
    const pr=r.pick(["low","normal","normal","high","urgent"]);const st=age>14?r.pick(["closed","resolved","resolved"]):age>3?r.pick(["open","waiting","resolved","open"]):r.pick(["new","open","new"]);
    const cname=ct.length?r.pick(ct).name:"Cliente";
    const msgs=[{from:cname,me:false,d:created.toISOString(),text:tr("Buenos días, les escribimos por lo siguiente: ","Good morning, we're writing about the following: ")+NV.L(TSUBJ[s]).toLowerCase()+tr(". Quedamos atentos.",". Looking forward to your reply.")}];
    if(st!=="new")msgs.push({from:REPS[i%4].name,me:true,d:new Date(created.getTime()+r.int(1,20)*36e5).toISOString(),text:tr("Hola, gracias por avisarnos. Ya lo derivamos a calidad y planta, les confirmamos hoy mismo los próximos pasos.","Hi, thanks for letting us know. We've passed it to quality and production and will confirm next steps today.")});
    if(st==="resolved"||st==="closed")msgs.push({from:REPS[i%4].name,me:true,d:new Date(created.getTime()+r.int(24,90)*36e5).toISOString(),text:tr("Quedó resuelto: se envió el reemplazo con el remito R-","Resolved: the replacement was shipped with delivery note R-")+r.int(10000,99999)+tr(". Cualquier cosa nos avisan.",". Let us know if you need anything else.")});
    tickets.push({id:"K"+String(i+1).padStart(3,"0"),ref:"TK-"+String(1180+i),subject:NV.L(TSUBJ[s]),company:c.id,contact:ct.length?ct[0].id:"",cat:r.pick(TCAT),priority:pr,status:st,assigned:REPS[i%4].id,created:created.toISOString(),sla:{urgent:8,high:24,normal:48,low:96}[pr],msgs})}
  tickets.sort((a,b)=>b.created.localeCompare(a.created));
  const campaigns=[["Lanzamiento gabinetes IP65 línea 2026","IP65 cabinet line 2026 launch","email",-80],["Newsletter industrial · Agosto","Industrial newsletter · August","newsletter",-55],["Invitación stand Expo Industria Córdoba","Córdoba Industry Expo booth invite","event",-38],["Webinar: inoxidable sanitario para alimentos","Webinar: sanitary stainless for food","webinar",-20],["Newsletter industrial · Septiembre","Industrial newsletter · September","newsletter",-12],["Reactivación clientes inactivos","Win-back inactive customers","email",-4],["Promo repuestos mecanizados Q4","Machined spare parts Q4 promo","email",9]].map(([es,en,type,dd],i)=>{const sent=dd<0?r.int(380,1400):0;const op=Math.round(sent*r.int(24,46)/100),cl=Math.round(op*r.int(12,30)/100);return {id:"M"+(i+1),name:[es,en],type,date:iso(addDays(today,dd)),status:dd<0?"sent":i===6?"scheduled":"draft",audience:r.pick([["Clientes activos","Active customers"],["Prospectos industria alimenticia","Food industry prospects"],["Toda la base","Whole database"],["Clientes inactivos +6 meses","Customers inactive 6+ months"]]),sent,opens:op,clicks:cl,leads:Math.round(cl*r.int(8,22)/100),subject:es}});
  return {companies,contacts,opps,leads,acts,quotes,tickets,campaigns};
}

/* ======================= HELPERS ======================= */
const C=id=>db().companies.find(c=>c.id===id)||{name:"—",id:""};
const PC=id=>db().contacts.find(c=>c.id===id);
const U=id=>REPS.find(u=>u.id===id)||{name:"—",id:""};
const S=id=>STAGES.find(s=>s.id===id);
const cLink=id=>`<a href="#/companies/card/${id}">${esc(C(id).name)}</a>`;
const uChip=id=>`<span style="display:inline-flex;gap:7px;align-items:center;white-space:nowrap"><span class="av sm">${initials(U(id).name)}</span>${esc(U(id).name.split(" ")[0])}</span>`;
const srcL=k=>NV.L((SOURCES.find(s=>s[0]===k)||[0,["—","—"]])[1]);
const isOpen=o=>o.stage!=="won"&&o.stage!=="lost";
const qcalc=q=>{const ht=q.lines.reduce((s,l)=>s+l.q*l.price*(1-(l.disc||0)/100),0);return {ht,tax:ht*.21,ttc:ht*1.21}};
const ACT={call:{ic:"phone",l:["Llamada","Call"],tone:""},meeting:{ic:"meet",l:["Reunión","Meeting"],tone:"vio"},email:{ic:"mail",l:["Email","Email"],tone:"ok"},visit:{ic:"building",l:["Visita","Visit"],tone:"warn"},task:{ic:"check",l:["Tarea","Task"],tone:"bad"}};
const LST={new:[["Nuevo","New"],"blue"],contacted:[["Contactado","Contacted"],"warn"],qualified:[["Calificado","Qualified"],"ok"],lost:[["Descartado","Disqualified"],"bad"],converted:[["Convertido","Converted"],"vio"]};
const QST={draft:[["Borrador","Draft"],""],sent:[["Enviada","Sent"],"blue"],accepted:[["Aceptada","Accepted"],"ok"],rejected:[["Rechazada","Rejected"],"bad"]};
const TST={new:[["Nuevo","New"],"blue"],open:[["En curso","In progress"],"warn"],waiting:[["Esperando cliente","Waiting on customer"],"vio"],resolved:[["Resuelto","Resolved"],"ok"],closed:[["Cerrado","Closed"],""]};
const TPR={low:[["Baja","Low"],""],normal:[["Normal","Normal"],"blue"],high:[["Alta","High"],"warn"],urgent:[["Urgente","Urgent"],"bad"]};
const MST={draft:[["Borrador","Draft"],""],scheduled:[["Programada","Scheduled"],"blue"],sent:[["Enviada","Sent"],"ok"]};
const MTYPE={email:["Email","Email"],newsletter:["Newsletter","Newsletter"],event:["Evento","Event"],webinar:["Webinar","Webinar"]};
const B=(map,k)=>badge(NV.L(map[k][0]),map[k][1]);
const opts=map=>Object.entries(map).map(([k,v])=>[k,v[0]]);
const stageBadge=k=>{const s=S(k);return `<span class="bd" style="background:color-mix(in srgb,${s.c} 14%,transparent);color:${s.c}">${esc(NV.L(s.name))}</span>`};
const slaLeft=t=>{const due=new Date(D2(t.created).getTime()+t.sla*36e5);return (due-new Date())/36e5};
const slaBadge=t=>{if(t.status==="resolved"||t.status==="closed")return "<span class='muted small'>—</span>";const h=slaLeft(t);return h<0?badge(tr("Vencido ","Breached ")+Math.round(-h)+"h","bad"):badge(Math.round(h)+"h "+tr("restantes","left"),h<8?"warn":"ok")};
const ym=s=>s.slice(0,7);
const monthsBack=n=>Array.from({length:n},(_,i)=>{const d=new Date(TODAY.getFullYear(),TODAY.getMonth()-(n-1-i),1);return {key:d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0"),label:monthName(d.getMonth())}});
const monthsFwd=n=>Array.from({length:n},(_,i)=>{const d=new Date(TODAY.getFullYear(),TODAY.getMonth()+i,1);return {key:d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0"),label:monthName(d.getMonth())}});
const H=(main,o)=>NV.head(main,o);
const append=(main,html)=>{const el=NV.el(html);main.appendChild(el);return el};
const nid=(p,arr)=>p+String(arr.length+1).padStart(3,"0")+Math.random().toString(36).slice(2,4);

