/* ======================= DASHBOARD ======================= */
function pageHome(main){const d=db();const open=d.opps.filter(isOpen);const pipe=open.reduce((s,o)=>s+o.amount,0),wpipe=open.reduce((s,o)=>s+o.amount*o.prob/100,0);
  const q0=new Date(TODAY.getFullYear(),Math.floor(TODAY.getMonth()/3)*3,1);const wonQ=d.opps.filter(o=>o.stage==="won"&&D2(o.close)>=q0);const closed=d.opps.filter(o=>!isOpen(o));const rate=closed.length?d.opps.filter(o=>o.stage==="won").length/closed.length*100:0;
  const todays=d.acts.filter(a=>iso(a.dt.slice(0,10))===iso(TODAY)||new Date(a.dt).toDateString()===TODAY.toDateString());
  H(main,{icon:"grid",title:tr("Panel comercial","Sales dashboard"),sub:tr("Hola, Sofía. Esto es lo que pasa hoy en tu equipo.","Hi Sofía. Here's what's happening with your team today.")+" · "+dateL(TODAY),actions:`<button class="btn" data-a="newAct">${icon("cal")}${tr("Actividad","Activity")}</button><button class="btn pri" data-a="newOpp">${icon("plus")}${tr("Oportunidad","Opportunity")}</button>`});
  append(main,`<div class="g g4">${NV.kpi("funnel",tr("Pipeline abierto","Open pipeline"),money(pipe),"",open.length+" "+tr("oportunidades","opportunities"))}${NV.kpi("target",tr("Pipeline ponderado","Weighted pipeline"),money(wpipe),"vio")}${NV.kpi("award",tr("Ganado este trimestre","Won this quarter"),money(wonQ.reduce((s,o)=>s+o.amount,0)),"ok",wonQ.length+" "+tr("negocios","deals"))}${NV.kpi("pie",tr("Tasa de cierre","Win rate"),num(rate,1)+"%","warn")}</div>`);
  const g=append(main,`<div class="g g-2-1 mt"><div class="card"><div class="card-h"><h3>${icon("funnel")}${tr("Pipeline por etapa","Pipeline by stage")}</h3><a class="small" href="#/pipeline">${tr("Abrir Kanban","Open Kanban")}</a></div><div class="card-b"><div class="chart"><canvas id="h1"></canvas></div></div></div>
   <div class="card"><div class="card-h"><h3>${icon("cal")}${tr("Agenda de hoy","Today's agenda")}</h3><a class="small" href="#/agenda">${tr("Calendario","Calendar")}</a></div><ul class="list-mini">${todays.map(a=>`<li><div class="l"><span class="kpi" style="padding:0"><span class="ki ${ACT[a.type].tone}" style="width:34px;height:34px">${icon(ACT[a.type].ic)}</span></span><div><b>${esc(a.title)}</b><small>${time(a.dt)} · ${esc(C(a.company).name)}</small></div></div>${a.done?badge(tr("Hecha","Done"),"ok"):`<button class="btn sm" data-done="${a.id}">${icon("check")}</button>`}</li>`).join("")||`<li class="muted">${tr("Nada agendado para hoy","Nothing scheduled today")}</li>`}</ul></div></div>`);
  const st=STAGES.filter(s=>s.id!=="lost"&&s.id!=="won");
  chart($("#h1",g),{type:"bar",money:true,legend:false,data:{labels:st.map(s=>NV.L(s.name)),datasets:[{label:tr("Monto","Amount"),data:st.map(s=>open.filter(o=>o.stage===s.id).reduce((a,o)=>a+o.amount,0)),backgroundColor:st.map(s=>s.c)}]}});
  const fw=monthsFwd(6);const g2=append(main,`<div class="g g3 mt"><div class="card"><div class="card-h"><h3>${icon("chart")}${tr("Pronóstico de cierre (ponderado)","Close forecast (weighted)")}</h3></div><div class="card-b"><div class="chart sm"><canvas id="h2"></canvas></div></div></div><div class="card"><div class="card-h"><h3>${icon("lead")}${tr("Leads por origen (45 días)","Leads by source (45 days)")}</h3></div><div class="card-b"><div class="chart sm"><canvas id="h3"></canvas></div></div></div><div class="card"><div class="card-h"><h3>${icon("award")}${tr("Ganado por vendedor (12 meses)","Won by rep (12 months)")}</h3></div><div class="card-b"><div class="chart sm"><canvas id="h4"></canvas></div></div></div></div>`);
  chart($("#h2",g2),{type:"bar",money:true,stacked:true,data:{labels:fw.map(m=>m.label),datasets:[{label:tr("Ponderado","Weighted"),data:fw.map(m=>open.filter(o=>ym(o.close)===m.key).reduce((s,o)=>s+o.amount*o.prob/100,0))},{label:tr("Resto del pipeline","Rest of pipeline"),data:fw.map(m=>open.filter(o=>ym(o.close)===m.key).reduce((s,o)=>s+o.amount*(1-o.prob/100),0)),color:NV.css("--line")}]}});
  chart($("#h3",g2),{type:"doughnut",data:{labels:SOURCES.map(s=>NV.L(s[1])),datasets:[{data:SOURCES.map(s=>d.leads.filter(l=>l.source===s[0]).length)}]}});
  chart($("#h4",g2),{type:"bar",horizontal:true,money:true,legend:false,data:{labels:REPS.map(u=>u.name.split(" ")[0]),datasets:[{label:tr("Ganado","Won"),data:REPS.map(u=>d.opps.filter(o=>o.stage==="won"&&o.owner===u.id).reduce((s,o)=>s+o.amount,0)),color:"#12A06A"}]}});
  const closing=open.filter(o=>D2(o.close)<=addDays(TODAY,30)).sort((a,b)=>a.close.localeCompare(b.close)).slice(0,6);
  const urgent=d.tickets.filter(t=>!["resolved","closed"].includes(t.status)).sort((a,b)=>slaLeft(a)-slaLeft(b)).slice(0,5);
  const nl=d.leads.filter(l=>l.status==="new").slice(0,5);
  append(main,`<div class="g g3 mt">
   <div class="card"><div class="card-h"><h3>${icon("target")}${tr("Cierran en los próximos 30 días","Closing in the next 30 days")}</h3></div><ul class="list-mini">${closing.map(o=>`<li><div class="l"><div><a href="#/pipeline/card/${o.id}"><b>${esc(o.title)}</b></a><small>${esc(C(o.company).name)} · ${date(o.close)}</small></div></div><div style="text-align:right"><b class="num">${money(o.amount)}</b><div>${stageBadge(o.stage)}</div></div></li>`).join("")||`<li class="muted">—</li>`}</ul></div>
   <div class="card"><div class="card-h"><h3>${icon("ticket")}${tr("Tickets por SLA","Tickets by SLA")}</h3><a class="small" href="#/tickets">${tr("Ver todos","View all")}</a></div><ul class="list-mini">${urgent.map(t=>`<li><div class="l"><div><a class="ref" href="#/tickets/card/${t.id}">${t.ref}</a><b style="font-weight:600">${esc(t.subject)}</b><small>${esc(C(t.company).name)}</small></div></div><div style="text-align:right">${B(TPR,t.priority)}<div style="margin-top:4px">${slaBadge(t)}</div></div></li>`).join("")}</ul></div>
   <div class="card"><div class="card-h"><h3>${icon("lead")}${tr("Leads nuevos sin contactar","New leads to contact")}</h3><a class="small" href="#/leads/new">${tr("Ver todos","View all")}</a></div><ul class="list-mini">${nl.map(l=>`<li><div class="l"><span class="av sm">${initials(l.name)}</span><div><b>${esc(l.name)}</b><small>${esc(l.company)} · ${esc(srcL(l.source))}</small></div></div><span class="tag">${l.score}</span></li>`).join("")||`<li class="muted">—</li>`}</ul></div></div>`);
  bindActs(main);$$("[data-done]",main).forEach(b=>b.onclick=()=>{db().acts.find(a=>a.id===b.dataset.done).done=true;save();toast(tr("Actividad completada","Activity completed"));NV.render()});}

/* ======================= LEADS ======================= */
function pageLeads(main,filter){
  H(main,{crumbs:[["Leads","#/leads"]],icon:"lead",title:filter==="new"?tr("Leads sin contactar","Leads not contacted"):filter==="qualified"?tr("Leads calificados","Qualified leads"):"Leads",sub:tr("Contactos entrantes antes de convertirse en oportunidad. El puntaje combina industria, tamaño e interacción.","Inbound contacts before they become opportunities. Score blends industry, size and engagement."),actions:`<button class="btn pri" data-a="newLead">${icon("plus")}${tr("Nuevo lead","New lead")}</button>`});
  table(main,{rows:()=>db().leads.filter(l=>filter?l.status===filter:l.status!=="converted").sort((a,b)=>b.created.localeCompare(a.created)),name:"leads",onRow:l=>leadModal(l),filters:[{k:"status",label:NV.t("status"),options:opts(LST)},{k:"source",label:tr("Origen","Source"),options:SOURCES},{k:"owner",label:NV.t("owner"),options:REPS.map(u=>[u.id,u.name])}],
   columns:[{k:"name",label:tr("Nombre","Name"),render:l=>`<div style="display:flex;gap:10px;align-items:center"><span class="av sm">${initials(l.name)}</span><div><b>${esc(l.name)}</b><div class="small muted">${esc(NV.L(l.role))}</div></div></div>`},{k:"company",label:tr("Empresa","Company"),render:l=>`${esc(l.company)}<div class="small muted">${esc(l.city)} · ${esc(NV.L(l.industry))}</div>`},{k:"source",label:tr("Origen","Source"),render:l=>`<span class="tag">${esc(srcL(l.source))}</span>`,text:l=>srcL(l.source)},{k:"interest",label:tr("Interés","Interest"),render:l=>`<span class="small">${esc(l.interest)}</span>`},
    {k:"score",label:tr("Puntaje","Score"),r:1,render:l=>`<div style="display:flex;gap:8px;align-items:center;justify-content:flex-end"><div class="bar ${l.score>70?"ok":l.score<35?"bad":"warn"}" style="width:60px"><i style="width:${l.score}%"></i></div><b>${l.score}</b></div>`},{k:"owner",label:NV.t("owner"),render:l=>uChip(l.owner),text:l=>U(l.owner).name},{k:"created",label:tr("Ingreso","Created"),render:l=>date(l.created)},{k:"status",label:NV.t("status"),render:l=>B(LST,l.status),text:l=>NV.L(LST[l.status][0])}]});bindActs(main);}
function leadModal(l){modal({title:l.name,body:`<div class="rec-h" style="padding:0 0 14px"><div class="big">${initials(l.name)}</div><div><h2>${esc(l.name)}</h2><div class="meta">${B(LST,l.status)}<span class="tag">${tr("Puntaje","Score")} ${l.score}</span><span class="muted">${esc(NV.L(l.role))} · ${esc(l.company)}</span></div></div></div><dl class="dl"><dt>Email</dt><dd>${esc(l.email)}</dd><dt>${tr("Teléfono","Phone")}</dt><dd>${esc(l.phone)}</dd><dt>${tr("Origen","Source")}</dt><dd>${esc(srcL(l.source))}</dd><dt>${tr("Industria","Industry")}</dt><dd>${esc(NV.L(l.industry))} · ${esc(l.city)}</dd><dt>${tr("Interés","Interest")}</dt><dd>${esc(l.interest)}</dd><dt>${NV.t("owner")}</dt><dd>${uChip(l.owner)}</dd><dt>${tr("Ingreso","Created")}</dt><dd>${date(l.created)}</dd></dl>`,
  actions:[{label:tr("Descartar","Disqualify"),cls:"bad",onClick:()=>{l.status="lost";save();toast(NV.t("saved"));NV.render()}},{label:tr("Marcar contactado","Mark contacted"),onClick:()=>{l.status="contacted";l.score=Math.min(100,l.score+10);save();toast(NV.t("saved"));NV.render()}},{label:tr("Convertir en oportunidad","Convert to opportunity"),primary:true,icon:"arrowR",onClick:()=>{setTimeout(()=>convertLead(l),0)}}]})}
function convertLead(l){formModal({title:tr("Convertir lead en oportunidad","Convert lead to opportunity"),fields:[{k:"title",label:tr("Título de la oportunidad","Opportunity title"),req:1,full:1,def:l.interest+" · "+l.company},{k:"amount",label:tr("Monto estimado (US$)","Estimated amount (US$)"),type:"number",def:25000,req:1},{k:"close",label:tr("Cierre estimado","Expected close"),type:"date",def:iso(addDays(TODAY,45))},{k:"owner",label:NV.t("owner"),type:"select",options:REPS.map(u=>[u.id,u.name]),def:l.owner}],onSave:v=>{const d=db();
  const c={id:nid("C",d.companies),name:l.company,city:l.city,prov:"",industry:l.industry,employees:0,web:"",phone:l.phone,owner:v.owner,status:"prospect",rating:3,created:iso(TODAY),cuit:"",notes:""};d.companies.push(c);
  const p={id:nid("P",d.contacts),name:l.name,company:c.id,role:l.role,email:l.email,phone:l.phone,last:iso(TODAY),tags:[]};d.contacts.push(p);
  const o={id:nid("O",d.opps),ref:"OP-"+(240+d.opps.length),title:v.title,company:c.id,contact:p.id,amount:Number(v.amount),stage:"qualify",prob:25,close:v.close,owner:v.owner,source:l.source,created:iso(TODAY),lost:null,next:["Agendar reunión técnica","Schedule technical meeting"],hist:[{d:iso(TODAY),txt:tr("Creada desde lead ","Created from lead ")+l.name}]};d.opps.push(o);l.status="converted";save();toast(tr("Lead convertido: empresa, contacto y oportunidad creados","Lead converted: company, contact and opportunity created"));NV.go("#/pipeline/card/"+o.id)}})}
function newLead(){formModal({title:tr("Nuevo lead","New lead"),fields:[{k:"name",label:tr("Nombre y apellido","Full name"),req:1},{k:"company",label:tr("Empresa","Company"),req:1},{k:"email",label:"Email",type:"email"},{k:"phone",label:tr("Teléfono","Phone")},{k:"source",label:tr("Origen","Source"),type:"select",options:SOURCES},{k:"owner",label:NV.t("owner"),type:"select",options:REPS.map(u=>[u.id,u.name])},{k:"interest",label:tr("Interés","Interest"),type:"select",options:CATALOG.map(c=>[NV.L(c[1]),c[1]]),full:1},{k:"city",label:tr("Localidad","City")}],onSave:v=>{db().leads.unshift({id:nid("L",db().leads),...v,role:["Contacto","Contact"],status:"new",score:40,created:iso(TODAY),industry:["Industria","Industry"]});save();toast(NV.t("created"));NV.go("#/leads")}})}

/* ======================= PIPELINE ======================= */
let ownerFilter="";
function pageKanban(main){
  H(main,{crumbs:[[tr("Oportunidades","Opportunities"),"#/pipeline"]],icon:"kanban",title:tr("Pipeline de ventas","Sales pipeline"),sub:tr("Arrastrá las tarjetas entre columnas para cambiar la etapa.","Drag cards between columns to change the stage."),actions:`<a class="btn" href="#/pipeline/list">${icon("list")}${tr("Vista lista","List view")}</a><button class="btn pri" data-a="newOpp">${icon("plus")}${tr("Nueva oportunidad","New opportunity")}</button>`});
  append(main,`<div class="chips" style="margin-bottom:14px"><button class="chip ${ownerFilter?"":"on"}" data-o="">${tr("Todo el equipo","Whole team")}</button>${REPS.map(u=>`<button class="chip ${ownerFilter===u.id?"on":""}" data-o="${u.id}">${esc(u.name)}</button>`).join("")}</div>`);
  const recent=o=>isOpen(o)||D2(o.close)>=addDays(TODAY,-45);
  const list=db().opps.filter(o=>(!ownerFilter||o.owner===ownerFilter)&&recent(o));
  const kb=append(main,`<div class="kb">${STAGES.map(s=>{const os=list.filter(o=>o.stage===s.id);return `<div class="kcol"><div class="kcol-h"><div class="top-l"><b><i style="background:${s.c}"></i>${esc(NV.L(s.name))}</b><span class="tag">${os.length}</span></div><small>${money(os.reduce((a,o)=>a+o.amount,0))} · ${s.p}%</small></div><div class="kcol-b" data-stage="${s.id}">${os.map(o=>`<div class="kc" draggable="true" data-id="${o.id}"><div class="row"><span class="ref">${o.ref}</span>${uChip(o.owner)}</div><b>${esc(o.title)}</b><div class="row"><span>${esc(C(o.company).name)}</span></div><div class="row"><span class="amt">${money(o.amount)}</span><span class="${isOpen(o)&&D2(o.close)<TODAY?"down":""}">${icon("cal","i")} ${date(o.close)}</span></div>${o.next&&isOpen(o)?`<div class="row" style="color:var(--ink-2)">${icon("arrowR","i")} ${esc(NV.L(o.next))}</div>`:""}</div>`).join("")}</div></div>`}).join("")}</div>`);
  $$("[data-o]",main).forEach(b=>b.onclick=()=>{ownerFilter=b.dataset.o;NV.render()});
  let drag=null;
  $$(".kc",kb).forEach(c=>{c.addEventListener("dragstart",e=>{drag=c.dataset.id;c.classList.add("drag");e.dataTransfer.effectAllowed="move";try{e.dataTransfer.setData("text/plain",drag)}catch(x){}});c.addEventListener("dragend",()=>c.classList.remove("drag"));c.addEventListener("click",()=>NV.go("#/pipeline/card/"+c.dataset.id))});
  $$(".kcol-b",kb).forEach(col=>{col.addEventListener("dragover",e=>{e.preventDefault();col.classList.add("over")});col.addEventListener("dragleave",()=>col.classList.remove("over"));col.addEventListener("drop",e=>{e.preventDefault();col.classList.remove("over");const o=db().opps.find(x=>x.id===drag);if(!o)return;const st=col.dataset.stage;if(st===o.stage)return;
    if(st==="lost"){lostModal(o);return}setStage(o,st);toast(tr("Etapa actualizada: ","Stage updated: ")+NV.L(S(st).name)+(st==="won"?" 🎉":""));NV.render()})});
  bindActs(main);}
function setStage(o,st){o.stage=st;o.prob=S(st).p;o.hist.push({d:iso(TODAY),txt:tr("Etapa → ","Stage → ")+NV.L(S(st).name)});if(st==="won"){o.close=iso(TODAY);o.next="";const c=C(o.company);if(c.id)c.status="customer"}save()}
function lostModal(o){formModal({title:tr("Marcar como perdida","Mark as lost"),fields:[{k:"reason",label:tr("Motivo","Reason"),type:"select",options:LOST.map((l,i)=>[i,l]),full:1},{k:"note",label:NV.t("notes"),type:"textarea",full:1}],onSave:v=>{o.lost=LOST[Number(v.reason)];o.close=iso(TODAY);o.next="";setStage(o,"lost");if(v.note)o.hist.push({d:iso(TODAY),txt:v.note});save();toast(NV.t("saved"));NV.render()}})}
function pageOppList(main){H(main,{crumbs:[[tr("Oportunidades","Opportunities"),"#/pipeline"]],icon:"list",title:tr("Oportunidades","Opportunities"),actions:`<a class="btn" href="#/pipeline">${icon("kanban")}Kanban</a><button class="btn pri" data-a="newOpp">${icon("plus")}${tr("Nueva","New")}</button>`});
  table(main,{rows:()=>db().opps.slice().sort((a,b)=>a.close.localeCompare(b.close)),name:"oportunidades",onRow:o=>NV.go("#/pipeline/card/"+o.id),pageSize:15,filters:[{k:"stage",label:tr("Etapa","Stage"),options:STAGES.map(s=>[s.id,s.name])},{k:"owner",label:NV.t("owner"),options:REPS.map(u=>[u.id,u.name])},{k:"source",label:tr("Origen","Source"),options:SOURCES}],
   columns:[{k:"ref",label:NV.t("ref"),render:o=>`<span class="ref">${o.ref}</span>`},{k:"title",label:tr("Oportunidad","Opportunity"),render:o=>`<b>${esc(o.title)}</b><div class="small muted">${esc(C(o.company).name)}</div>`,text:o=>o.title},{k:"amount",label:tr("Monto","Amount"),r:1,render:o=>`<b>${money(o.amount)}</b>`},{k:"prob",label:"%",r:1},{k:"w",label:tr("Ponderado","Weighted"),r:1,sv:o=>o.amount*o.prob/100,text:o=>o.amount*o.prob/100,render:o=>money(o.amount*o.prob/100)},{k:"close",label:tr("Cierre","Close"),render:o=>`<span class="${isOpen(o)&&D2(o.close)<TODAY?"down strong":""}">${date(o.close)}</span>`},{k:"owner",label:NV.t("owner"),render:o=>uChip(o.owner),text:o=>U(o.owner).name},{k:"stage",label:tr("Etapa","Stage"),sv:o=>STAGES.findIndex(s=>s.id===o.stage),render:o=>stageBadge(o.stage),text:o=>NV.L(S(o.stage).name)}],
   footer:a=>`<tr><td colspan="2">${NV.t("total")} (${a.length})</td><td class="num">${money(a.reduce((s,o)=>s+o.amount,0))}</td><td></td><td class="num">${money(a.reduce((s,o)=>s+o.amount*o.prob/100,0))}</td><td colspan="3"></td></tr>`});bindActs(main);}
