function actModal(a){modal({title:a.title,body:`<dl class="dl"><dt>${tr("Tipo","Type")}</dt><dd>${esc(NV.L(ACT[a.type].l))}</dd><dt>${NV.t("date")}</dt><dd>${dateL(a.dt)} · ${time(a.dt)}${a.dur?" ("+a.dur+" min)":""}</dd><dt>${tr("Empresa","Company")}</dt><dd>${cLink(a.company)}</dd>${a.opp?`<dt>${tr("Oportunidad","Opportunity")}</dt><dd><a href="#/pipeline/card/${a.opp}">${esc(db().opps.find(o=>o.id===a.opp)?.title||"")}</a></dd>`:""}<dt>${NV.t("owner")}</dt><dd>${uChip(a.owner)}</dd><dt>${NV.t("status")}</dt><dd>${a.done?badge(tr("Hecha","Done"),"ok"):badge(tr("Pendiente","Pending"),"warn")}</dd>${a.notes?`<dt>${NV.t("notes")}</dt><dd>${esc(a.notes)}</dd>`:""}</dl>`,
  actions:[{label:NV.t("del"),cls:"bad",onClick:()=>{db().acts=db().acts.filter(x=>x!==a);save();toast(NV.t("deleted"));NV.render()}},{label:NV.t("close")},...(a.done?[]:[{label:tr("Marcar hecha","Mark done"),primary:true,icon:"check",onClick:()=>{a.done=true;save();toast(tr("Actividad completada","Activity completed"));NV.render()}}])]})}
function newAct(pre={}){formModal({title:tr("Nueva actividad","New activity"),fields:[{k:"type",label:tr("Tipo","Type"),type:"select",options:Object.entries(ACT).map(([k,v])=>[k,v.l])},{k:"title",label:tr("Asunto","Subject"),req:1},{k:"date",label:NV.t("date"),type:"date",def:pre.date||iso(TODAY)},{k:"time",label:tr("Hora","Time"),type:"time",def:"10:00"},{k:"company",label:tr("Empresa","Company"),type:"select",options:db().companies.map(c=>[c.id,c.name]).sort((a,b)=>a[1].localeCompare(b[1])),def:pre.company},{k:"owner",label:NV.t("owner"),type:"select",options:REPS.map(u=>[u.id,u.name])},{k:"notes",label:NV.t("notes"),type:"textarea",full:1}],
  onSave:v=>{const dt=new Date(v.date+"T"+(v.time||"10:00")+":00");db().acts.push({id:nid("A",db().acts),type:v.type,title:v.title,dt:dt.toISOString(),dur:30,company:v.company,opp:pre.opp||"",owner:v.owner,done:false,notes:v.notes});save();toast(NV.t("created"));NV.render()}})}
function pageCalendar(main){if(!calMonth)calMonth=new Date(TODAY.getFullYear(),TODAY.getMonth(),1);
  const y=calMonth.getFullYear(),m=calMonth.getMonth();const title=calMonth.toLocaleDateString(NV.lang==="en"?"en-US":"es-AR",{month:"long",year:"numeric"});
  H(main,{crumbs:[[tr("Agenda","Agenda"),"#/agenda"]],icon:"cal",title:title.charAt(0).toUpperCase()+title.slice(1),actions:`<button class="btn" data-m="-1" aria-label="${NV.t("prev")}">${icon("arrowL")}</button><button class="btn" data-m="0">${NV.t("today")}</button><button class="btn" data-m="1" aria-label="${NV.t("next")}">${icon("arrowR")}</button><button class="btn pri" data-a="newAct">${icon("plus")}${tr("Actividad","Activity")}</button>`});
  append(main,`<div class="chips" style="margin-bottom:12px">${Object.entries(ACT).map(([k,v])=>`<span class="bd ${v.tone||"blue"}">${esc(NV.L(v.l))}</span>`).join("")}</div>`);
  const first=new Date(y,m,1);const start=addDays(first,-((first.getDay()+6)%7));const days=Array.from({length:42},(_,i)=>addDays(start,i));
  const dn=Array.from({length:7},(_,i)=>addDays(new Date(2026,0,5),i).toLocaleDateString(NV.lang==="en"?"en-US":"es-AR",{weekday:"short"}));
  const byDay={};db().acts.forEach(a=>{const k=new Date(a.dt).toDateString();(byDay[k]=byDay[k]||[]).push(a)});
  const cal=append(main,`<div class="card" style="overflow:hidden"><div class="cal">${dn.map(d=>`<div class="dh">${esc(d)}</div>`).join("")}${days.map(d=>{const ev=(byDay[d.toDateString()]||[]).sort((a,b)=>a.dt.localeCompare(b.dt));return `<div class="dc ${d.getMonth()!==m?"out":""} ${d.toDateString()===TODAY.toDateString()?"today":""}" data-day="${iso(d)}"><span class="n">${d.getDate()}</span>${ev.slice(0,3).map(a=>`<span class="ev ${ACT[a.type].tone}" data-ev="${a.id}" title="${esc(a.title)}" style="${a.done?"opacity:.6;text-decoration:line-through":""}">${time(a.dt)} ${esc(a.title)}</span>`).join("")}${ev.length>3?`<span class="more">+${ev.length-3}</span>`:""}</div>`}).join("")}</div></div>`);
  $$("[data-m]",main).forEach(b=>b.onclick=()=>{const k=Number(b.dataset.m);calMonth=k?new Date(y,m+k,1):new Date(TODAY.getFullYear(),TODAY.getMonth(),1);NV.render()});
  $$("[data-ev]",cal).forEach(e=>e.onclick=ev=>{ev.stopPropagation();actModal(db().acts.find(a=>a.id===e.dataset.ev))});
  $$("[data-day]",cal).forEach(c=>c.onclick=()=>newAct({date:c.dataset.day}));bindActs(main);}
