    if(!ed)return;$$("[data-l]",lw).forEach(inp=>inp.onchange=()=>{const l=q.lines[inp.dataset.l];if(inp.dataset.f==="p"){const c=CATALOG.find(x=>x[0]===inp.value);l.p=c[0];l.desc=c[1];l.price=c[2]}else l[inp.dataset.f]=Number(inp.value)||0;save();NV.render()});
